function validate([tops, bottoms]) {
  if (tops.length < 2 || tops.length > 20000) return 'tops needs 2 to 20000 values.';
  if (bottoms.length !== tops.length) return 'tops and bottoms must have the same length.';
  if ([...tops, ...bottoms].some(v => !Number.isInteger(v) || v < 1 || v > 6)) return 'Every half shows a number from 1 to 6.';
  return null;
}

