function minDominoRotations(tops, bottoms) {
  let best = Infinity;
  for (const target of [tops[0], bottoms[0]]) {
    let topSwaps = 0;
    let bottomSwaps = 0;
    let possible = true;
    for (let i = 0; i < tops.length; i++) {
      if (tops[i] !== target && bottoms[i] !== target) {
        possible = false;
        break;
      }
      if (tops[i] !== target) {
        topSwaps++;
      }
      if (bottoms[i] !== target) {
        bottomSwaps++;
      }
    }
    if (possible) {
      best = Math.min(best, topSwaps, bottomSwaps);
    }
  }
  return best === Infinity ? -1 : best;
}

