function minDominoRotations(tops, bottoms) {
  let answer = -1;
  for (let value = 1; value <= 6; value++) {
    for (const [row, other] of [[tops, bottoms], [bottoms, tops]]) {
      let count = 0;
      let ok = true;
      row.forEach((v, i) => {
        if (v === value) return;
        if (other[i] === value) count++;
        else ok = false;
      });
      if (ok && (answer === -1 || count < answer)) answer = count;
    }
  }
  return answer;
}

