function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : int(2, 7);
  const top = size === 'small' && rand() < 0.3 ? 3 : 6;
  const tops = [];
  const bottoms = [];
  // Most inputs are built around one value so that a rotation plan exists.
  const solvable = rand() < 0.75;
  const value = int(1, top);
  for (let i = 0; i < n; i++) {
    let a = int(1, top);
    let b = int(1, top);
    if (solvable) {
      if (rand() < 0.5) a = value;
      else b = value;
    }
    tops.push(a);
    bottoms.push(b);
  }
  return [tops, bottoms];
}
